.venv/bin/python -c "import pandas as pd; import numpy as np; df = pd.read_csv('train.csv');
for f in ['x43', 'x11', 'x42', 'x02']:
    print(f'{f}:', np.corrcoef(df[f], df['target'])[0, 1])
    print(f'{f}^2:', np.corrcoef(df[f]**2, df['target'])[0, 1])
    print(f'{f}^3:', np.corrcoef(df[f]**3, df['target'])[0, 1])
"
